use std::rc::Rc;use std::cell::RefCell;impl Solution{pub fn is_symmetric(root:Option<Rc<RefCell<TreeNode>>>)->bool{fn m(a:Option<Rc<RefCell<TreeNode>>>,b:Option<Rc<RefCell<TreeNode>>>)->bool{match(a,b){(None,None)=>true,(Some(x),Some(y))=>{let x=x.borrow();let y=y.borrow();x.val==y.val&&m(x.left.clone(),y.right.clone())&&m(x.right.clone(),y.left.clone())},_=>false}}if let Some(r)=root{let r=r.borrow();m(r.left.clone(),r.right.clone())}else{true}}}
